<div class="erp-page-head"><form class="erp-filter" method="get"><input class="form-control form-control-sm" name="q" value="<?= e($_GET['q'] ?? '') ?>" placeholder="Username">
<select class="form-select form-select-sm" name="status"><option value="">Semua</option><?php foreach (['SUCCESS', 'FAILED', 'LOCKED', 'LOGOUT', 'INACTIVE'] as $s): ?><option <?= ($_GET['status'] ?? '') === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-secondary">Filter</button></form></div>
<div class="card erp-card"><div class="table-responsive"><table class="table table-sm erp-table mb-0" data-testid="login-history-table"><thead><tr><th>Waktu</th><th>Username</th><th>Nama</th><th>Status</th><th>Kanal</th><th>IP</th><th>User Agent</th></tr></thead><tbody>
<?php foreach ($page->items as $r): $c = ['SUCCESS' => 'success', 'LOGOUT' => 'secondary', 'FAILED' => 'danger', 'LOCKED' => 'dark', 'INACTIVE' => 'warning'][$r['status']]; ?>
<tr><td class="small text-nowrap"><?= fmt_date($r['created_at'], 'd/m/Y H:i:s') ?></td><td class="font-monospace"><?= e($r['username_attempted']) ?></td><td><?= e($r['full_name'] ?? '-') ?></td><td><span class="badge text-bg-<?= $c ?>"><?= $r['status'] ?></span></td><td><?= $r['channel'] ?></td><td class="small"><?= e($r['ip_address']) ?></td><td class="small text-muted text-truncate" style="max-width:280px"><?= e($r['user_agent']) ?></td></tr><?php endforeach; ?>
</tbody></table></div><div class="card-footer py-1"><?php $this->load->view('partials/pagination', ['page' => $page]); ?></div></div>
